#!/bin/bash
# shellcheck disable=SC2015
set -eEuo pipefail
# pinnebergRolle Stufe 1. Nummer bewusst offen, nicht commit65.
# Stick 3 wird nur reserviert. Kein Empfangsprogramm, kein Bias-Tee, kein apt, kein Neustart von prepper-sdr.
# Voraussetzung ist der installierte commit64. Bestaetigte lage_pages.py bleibt die Kuerzung.
# Aufruf: bash apply-pinneberg-rolle.sh pinnebergRolle [dry-run]
# Simulation: DASH_PORT=5093 C61_SIM_DIR C61_SIM_W C61_FAKE_HM C61_RETRY_S C61_WAIT_S C61_SIM_NOMUT C61_READY_S
COMMIT_ARG="${1:-unbekannt}"
MODE_ARG="${2:-}"
case "$MODE_ARG" in ""|dry-run|--dry-run|dryrun|trockenlauf) ;; *) echo "STOP: unbekannter zweiter Parameter '$MODE_ARG' (erlaubt: dry-run) - nichts geaendert"; exit 1;; esac
DRY=0; [[ -n "$MODE_ARG" ]] && DRY=1
DASH_DIR="/home/fmg/prepper-dashboard"
W=/tmp/pinneberg-apply
NM=pinnebergrolle
MK=pinnebergRolle
SIM=0; [[ -n "${DASH_PORT:-}" && "${DASH_PORT:-}" != 5000 ]] && SIM=1
if [[ "$SIM" == 1 ]]; then DASH_DIR="${C61_SIM_DIR:-$DASH_DIR}"; W="${C61_SIM_W:-$W}"; fi
VPY="$DASH_DIR/venv/bin/python"
SPY=/usr/bin/python3
TS=$(date +%Y%m%d-%H%M%S)
KEEP_LAST=3
SINGLE=(dashboard.py prepper_docs.py prepper_sdr.py)
declare -A ALT=(
  [dashboard.py]=5858908eaf6498bbcb737ad4791adb0bba0e4c7f4be0657f0bb31cdbef157a1d
  [prepper_docs.py]=36804387c50cba2b2021c71eaef1babc7aee85ebb0042e0849fa2267013d9937
  [prepper_sdr.py]=b879ab56f4ac47367afec20c904d3f1e274bc5ed154cd434a25b3bb8ca84b0bb
)
declare -A NEU=(
  [dashboard.py]=6d9fe2860fc636713461fd22b78de03941e23d167b7475e608f773fd0e5650b9
  [prepper_docs.py]=c26252d54344ca25875a5cf3e79b31df879af18ff9c504ec008a8ffff0080910
  [prepper_sdr.py]=533b6f9db8da0bcb73ca0e956bfc7a2edfade287375aa4eaf21f10a4ab37fb32
)
ROLLE_NEU=981cacdbf5a81348f9b32f67ac1c9ca27382af916d340c3b7773a84e87df06f5
JSON_NEU=e091123291a188749e7f6ea28f72672ae3bc314120a45bb5da8ed0fa08e58e8f
D64=5858908eaf6498bbcb737ad4791adb0bba0e4c7f4be0657f0bb31cdbef157a1d
D63=8a055ad3ed0619f681e2575c5ad588c3a28330eba1c00daab46d1cde46e28908
LAGE_TRIM=6b10e3bae7118d9519760b492220e88a5caf2e9dc99e9ed8db096eb911d0e778
LAGE_FULL=d268d324f4fd55a53cb7ee1919e3fb399e2c4ca0a7733780c9bf977b0fee2fca
UPS_KEEP=b2e491e36a9a1861de4c609f80a613f9b824e4f6f52319c50e5c5a87252ddcf8
declare -A KEEP=(
  [gas_saison.py]=1a258f195e59528b23841e350fdf505959d461f7779c7969ef0264980ee875d4
  [sdr_manager.py]=5a26efff608bf541
  [database.py]=2754d0bdddca9400
  [prepper_evlog.py]=8bffd396972b60fa
)
PHASE=vorher
FINISHED=0
RESTARTED=0
STOPPED=0
RB_DONE=0
INST=()
CREATED=()
VARIANT=""
LH0=""
ERRLN=""; ERRCMD=""
trap 'ERRLN=$LINENO; ERRCMD=$BASH_COMMAND' ERR
stop() { STOPPED=1; echo "STOP: $1 - nichts geaendert"; exit 1; }
CFG_PORT=$(sed -n 's/^PORT[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p' "$DASH_DIR/config.py" 2>/dev/null | head -1 || true)
PORT="${DASH_PORT:-${CFG_PORT:-5000}}"
if ! [[ "$PORT" =~ ^[0-9]+$ ]]; then stop "Dashboard-Port unklar ($PORT)"; fi
if [[ "$PORT" == "8080" ]]; then stop "Port 8080 ist kiwix-serve, nicht das Dashboard"; fi
if [[ "$SIM" == 1 && "$PORT" != "5093" ]]; then stop "Simulation nur auf Port 5093 (jetzt $PORT)"; fi
if [[ "$SIM" == 0 && "$PORT" != "5000" ]]; then stop "Echter Lauf nur auf Port 5000 (jetzt $PORT)"; fi
B="http://127.0.0.1:${PORT}"
CURL=(curl --compressed -s --connect-timeout 3 --max-time 40)
[[ -x "$SPY" ]] || stop "System-Python $SPY fehlt oder ist nicht ausfuehrbar"
if [[ ! -x "$VPY" ]]; then stop "Dashboard-venv $VPY fehlt oder ist nicht ausfuehrbar. Kein Rueckfall auf das System-Python."; fi
if ! "$VPY" -c 'import flask,sys; assert sys.version_info>=(3,9); assert sys.prefix!=sys.base_prefix, sys.prefix'; then
  stop "Dashboard-venv $VPY laedt Flask nicht oder ist kein eigenes venv. Nichts wird nachinstalliert und nichts auf $SPY umgebogen."
fi
for t in python3 sha256sum curl flock cp mv cmp stat date timeout nice base64; do command -v "$t" >/dev/null 2>&1 || stop "Werkzeug $t fehlt"; done
s16() { sha256sum "$1" | cut -c1-16; }
sfull() { sha256sum "$1" | cut -d' ' -f1; }
on_exit() {
  local ec=$?
  if [[ $ec -ne 0 && $FINISHED -eq 0 ]]; then
    if [[ "$PHASE" == vorher ]]; then
      [[ -n "$ERRLN" && "$STOPPED" == 0 ]] && echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile $ERRLN, Befehl: $(echo "$ERRCMD" | cut -c1-400) - es wurde noch nichts geaendert"
    elif [[ "$PHASE" == installiert && "$RB_DONE" == 0 ]]; then
      echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile ${ERRLN:-?}, Befehl: $(echo "${ERRCMD:-?}" | cut -c1-400) - Rollback"
      rb "unerwarteter Fehler" || true
    fi
  fi
}
trap on_exit EXIT
echo "=== $MK Stufe 1 ($COMMIT_ARG$([[ "$DRY" == 1 ]] && echo ", TROCKENLAUF")): Stick 3 reservieren, Port $PORT, Ordner $DASH_DIR ==="
echo "Nummer offen, nicht commit65. Kein apt, kein Empfangsprogramm, prepper-sdr wird nicht neu gestartet."
umask 022
mkdir -p "$(dirname "$W")"
exec 9>"$W.lock"
flock -n 9 || stop "ein anderer $NM-Lauf ist aktiv (Sperre $W.lock)"
rm -rf "$W" && mkdir -p "$W/neu" "$W/alt" "$W/html" && chmod 700 "$W"
python3 - "$W/neu" << 'MK_PAY_EOF'
import base64, hashlib, os, sys
dest = sys.argv[1]
os.makedirs(dest, exist_ok=True)
raw = {
    'dashboard.py': '',
    'prepper_docs.py': '',
    'prepper_sdr.py': '',
    'pinneberg_rolle.py': '',
    'pinneberg_rolle.json': 'eyJhcm1lZCI6IHRydWUsICJhdWRpb19vZmZzZXRfaHoiOiBudWxsLCAiYmF1ZCI6IDUwLCAiYmlhc190ZWUiOiBmYWxzZSwgImVtcGZhbmciOiBmYWxzZSwgImlmX2h6IjogMTIwMTQ3MzAwLCAicmZfaHoiOiAxNDczMDAsICJyb2xsZSI6ICJwaW5uZWJlcmciLCAic2hpZnRfaHoiOiA4NSwgInN0dWZlIjogMX0K',
}
expect = {
    'dashboard.py': '6d9fe2860fc636713461fd22b78de03941e23d167b7475e608f773fd0e5650b9',
    'prepper_docs.py': 'c26252d54344ca25875a5cf3e79b31df879af18ff9c504ec008a8ffff0080910',
    'prepper_sdr.py': '533b6f9db8da0bcb73ca0e956bfc7a2edfade287375aa4eaf21f10a4ab37fb32',
    'pinneberg_rolle.py': '981cacdbf5a81348f9b32f67ac1c9ca27382af916d340c3b7773a84e87df06f5',
    'pinneberg_rolle.json': 'e091123291a188749e7f6ea28f72672ae3bc314120a45bb5da8ed0fa08e58e8f',
}
for name, b64 in raw.items():
    data = base64.b64decode(b64)
    got = hashlib.sha256(data).hexdigest()
    if got != expect[name]:
        sys.stderr.write("FEHLER sha256 %s %s\n" % (name, got))
        sys.exit(1)
    tmp = os.path.join(dest, name + ".tmp")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, os.path.join(dest, name))
print("OK Nutzlast sha256 geprueft (%d Dateien)" % len(raw))
MK_PAY_EOF
EXPECT_GRD='c637129a48f1d4f470da8db25c118955ea997c961bf7be07b5bab3df11374b22'
cat > "$W/guard.py" << 'MK_GRD_EOF'
#!/usr/bin/env python3
"""guard pinnebergRolle Stufe 1. Prueft die Reservierung, nicht einen Decoder."""
import sys

SHUT = "Abschaltung bei 20 % oder 5 min · upsmon aktiv"


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def routes(src):
    return src.count("@app.route("), src.count("add_url_rule(")


def chk(alt_dash, neu):
    err = []
    d, docs, sdr, pn = neu["dashboard.py"], neu["prepper_docs.py"], neu["prepper_sdr.py"], neu["pinneberg_rolle.py"]
    lage = neu["lage_pages.py"]
    if "IF_HZ = LO_HZ + RF_HZ" not in pn or "RF_HZ = 147300" not in pn or "SHIFT_HZ = 85" not in pn:
        err.append("Frequenz oder Shift fehlt")
    if "AUDIO_OFFSET_HZ = None" not in pn or "+ 1900" in pn or "+1900" in pn:
        err.append("1900 Hz wurde als Sendersatz uebernommen")
    if "BIAS_TEE = False" not in pn or "rtl_fm" in pn or "Popen" in pn or '"-T"' in pn:
        err.append("Stufe 1 startet ein Programm oder einen Bias-Tee")
    if 'return {"code": "maritim", "alarm": False' not in pn:
        err.append("maritimer Text kann eine Warnung werden")
    if "if len(hits) != 1:" not in pn:
        err.append("Preflight akzeptiert eine unklare USB-Rolle")
    if "serial" in pn.split("def _public", 1)[-1].split("def http_status", 1)[0] and '"serial"' in pn.split("def _public", 1)[-1].split("def http_status", 1)[0]:
        err.append("API gibt eine Seriennummer aus")
    hook = sdr.split("pinnebergRolle Stufe 1", 1)[-1]
    want = hook.split("def _pn_want", 1)[-1].split("def _pn_bc_queue", 1)[0]
    if "_pn.engaged" not in want or 'return "idle"' not in want or "APRS wird nicht uebernommen" not in hook:
        err.append("Stick 3 sendet weiter APRS oder Stick 2 übernimmt es")
    if "x == \"433\"" not in hook and "x == '433'" not in hook:
        err.append("Stick 2 bekommt APRS")
    if "air_gain" in hook or "11D" in hook.split("def _pn_lage_apply", 1)[-1].split("def _pn_want", 1)[0]:
        err.append("Airspy wird angefasst")
    rd, ra = routes(d), routes(alt_dash)
    if rd[0] != ra[0] or (("/api/pinneberg" in alt_dash and rd[1] != ra[1]) or ("/api/pinneberg" not in alt_dash and rd[1] != ra[1] + 1)):
        err.append("Routen anders als die eine lesende API")
    if 'add_url_rule("/api/pinneberg", endpoint="pn_status", view_func=_pn_api, methods=["GET"])' not in d:
        err.append("API ist nicht nur lesend")
    if "mesh" in d.split("def _pn_api", 1)[-1].split("def _pn_after", 1)[0]:
        err.append("Anzeige sendet")
    if "USVA_LOW_S = 300" not in d or d.count(SHUT) != 3:
        err.append("USV-Schwelle geaendert")
    if "stimmeDe" not in docs or "pinnebergRolle" not in docs or "147,3 kHz" not in docs:
        err.append("Projektbeschreibung ohne Rolle oder ohne Stimme")
    if "kein Bias-Tee" not in docs and "keinen Bias-Tee" not in docs:
        err.append("Doku verschweigt den Bias-Tee")
    if "installiert nichts" not in docs and "Kein Paket wird installiert" not in docs:
        err.append("Doku verschweigt, dass kein Paket installiert wird")
    note = 'get("scenario_note")' in lage
    prof = 'get("profile_text")' in lage
    if neu.get("_variant") == "trim" and (note or prof):
        err.append("Speicher-Kuerzung wurde rueckgaengig gemacht")
    if neu.get("_variant") == "full" and not (note and prof):
        err.append("ungekuerzte Speicher-Seite verliert Profil oder Szenariohinweis")
    return err


def main():
    if len(sys.argv) < 5:
        print("Aufruf: guard.py check|mutate ALT NEU trim|full")
        sys.exit(2)
    cmd, alt, neu, variant = sys.argv[1:5]
    files = {}
    for name in ("dashboard.py", "prepper_docs.py", "prepper_sdr.py", "pinneberg_rolle.py", "lage_pages.py"):
        files[name] = read("%s/%s" % (neu, name))
    files["_variant"] = variant
    alt_dash = read("%s/dashboard.py" % alt)
    if cmd == "check":
        e = chk(alt_dash, files)
        if e:
            print("\n".join("VERSTOSS " + x for x in e))
            sys.exit(1)
        print("Guard pinnebergRolle ok: Stufe 1 reserviert nur, kein Programm, keine Warnung, Kuerzung bleibt")
        return
    pn, sdr, d, lage = files["pinneberg_rolle.py"], files["prepper_sdr.py"], files["dashboard.py"], files["lage_pages.py"]

    def put(**kw):
        out = dict(files)
        out.update(kw)
        return out

    mut = [
        ("1900 Hz addiert", put(**{"pinneberg_rolle.py": pn.replace("IF_HZ = LO_HZ + RF_HZ", "IF_HZ = LO_HZ + RF_HZ + 1900", 1)})),
        ("Bias-Tee an", put(**{"pinneberg_rolle.py": pn.replace("BIAS_TEE = False", "BIAS_TEE = True", 1)})),
        ("Programmstart", put(**{"pinneberg_rolle.py": pn.replace("argv\": None", "argv\": [\"rtl_fm\"]", 1)})),
        ("Warnung aus Text", put(**{"pinneberg_rolle.py": pn.replace('return {"code": "maritim", "alarm": False', 'return {"code": "maritim", "alarm": True', 1)})),
        ("USB egal", put(**{"pinneberg_rolle.py": pn.replace("if len(hits) != 1:", "if False and len(hits) != 1:", 1)})),
        ("Stick 2 übernimmt APRS", put(**{"prepper_sdr.py": sdr.replace('(self.cfg.get("auto") or []) if x == "433"', '(self.cfg.get("auto") or []) if x in ("433", "aprs")', 1)})),
        ("Stick 3 bleibt auf Sendung", put(**{"prepper_sdr.py": sdr.replace('if _s3e_is_h2(self) and _pn.engaged(getattr(self, "base", None)):\n            return "idle"', 'if False:\n            return "idle"', 1)})),
        ("API schreibt", put(**{"dashboard.py": d.replace('"/api/pinneberg", endpoint="pn_status", view_func=_pn_api, methods=["GET"]', '"/api/pinneberg", endpoint="pn_status", view_func=_pn_api, methods=["POST"]', 1)})),
        ("USV-Schwelle", put(**{"dashboard.py": d.replace("USVA_LOW_S = 300", "USVA_LOW_S = 60", 1)})),
        ("Kuerzung zurueck" if variant == "trim" else "Profilzeile weg", put(**{"lage_pages.py": lage + '\nget("scenario_note")\nget("profile_text")\n' if variant == "trim" else lage.replace('get("scenario_note")', 'get("scenario_x")', 1)})),
    ]
    bad = 0
    for name, changed in mut:
        e = chk(alt_dash, changed)
        print(("erkannt  " if e else "UEBERSEHEN ") + name + (": " + e[0] if e else ""))
        if not e:
            bad += 1
    print("Mutationstest pinnebergRolle: %d/%d erkannt" % (len(mut) - bad, len(mut)))
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
MK_GRD_EOF
echo "$EXPECT_GRD  $W/guard.py" | sha256sum -c - >/dev/null 2>&1 || stop "sha256 von guard.py falsch (Skript beschaedigt oder veraendert - bitte neu laden)"
echo "OK eingebettete Nutzlast und Guard geprueft"
for f in "${SINGLE[@]}" lage_pages.py ups_manager.py "${!KEEP[@]}"; do [[ -f "$DASH_DIR/$f" ]] || stop "$f fehlt im Projektordner $DASH_DIR"; done
NA=0; NN=0; ODD=""
for f in "${SINGLE[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$h" == "${ALT[$f]}" ]]; then NA=$((NA+1))
  elif [[ "$h" == "${NEU[$f]}" ]]; then NN=$((NN+1))
  elif [[ "$f" == dashboard.py && "$h" == "$D63" ]]; then stop "dashboard.py ist noch commit63 (${h:0:16}). Erst commit64 installieren. Eine Mischbasis wird nicht akzeptiert."
  elif [[ "$f" == dashboard.py && "$h" != "$D64" && "$h" != "${NEU[$f]}" ]]; then stop "dashboard.py ${h:0:16} ist nicht commit64 (${D64:0:16}). Erst commit64, dann diese Rolle."
  else ODD+="$f=${h:0:16} "; fi
done
[[ -z "$ODD" ]] || stop "Stand weicht ab (pinnebergRolle setzt commit64 voraus): ${ODD}"
RH="MISSING"; [[ -f "$DASH_DIR/pinneberg_rolle.py" ]] && RH=$(sfull "$DASH_DIR/pinneberg_rolle.py")
if [[ "$RH" == MISSING ]]; then PN=missing
elif [[ "$RH" == "$ROLLE_NEU" ]]; then PN=neu
else stop "pinneberg_rolle.py ${RH:0:16} ist weder fehlend noch der Zielstand ${ROLLE_NEU:0:16}"; fi
JH="MISSING"; [[ -f "$DASH_DIR/pinneberg_rolle.json" ]] && JH=$(sfull "$DASH_DIR/pinneberg_rolle.json")
if [[ "$JH" == MISSING ]]; then JS=missing
elif [[ "$JH" == "$JSON_NEU" ]]; then JS=neu
else stop "pinneberg_rolle.json ${JH:0:16} ist ein fremder Stand. Nichts wird ueberschrieben."; fi
LH=$(sfull "$DASH_DIR/lage_pages.py"); LH0="$LH"
case "$LH" in
  "$LAGE_TRIM") VARIANT=trim; echo "OK lage_pages.py bleibt die bestaetigte Kuerzung ${LH:0:16}";;
  "$LAGE_FULL") VARIANT=full; echo "OK lage_pages.py bleibt die ungekuerzte commit63-Fassung ${LH:0:16}";;
  *) stop "lage_pages.py ${LH:0:16} ist nicht die commit64-Basis (trim ${LAGE_TRIM:0:16} oder full ${LAGE_FULL:0:16}).";;
esac
UH=$(sfull "$DASH_DIR/ups_manager.py")
[[ "$UH" == "$UPS_KEEP" ]] || stop "ups_manager.py ${UH:0:16} ist nicht der commit63-Stand"
KODD=""
for f in "${!KEEP[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$f" == gas_saison.py ]]; then [[ "$h" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "
  else [[ "${h:0:16}" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "; fi
done
[[ -z "$KODD" ]] || stop "Unveraenderte Dateien weichen ab: ${KODD}"
if [[ "$NA" == 3 && "$PN" == missing && "$JS" == missing ]]; then STATE=alt; echo "OK Basis commit64, Variante $VARIANT"
elif [[ "$NN" == 3 && "$PN" == neu && "$JS" == neu ]]; then STATE=neu; echo "OK $MK ist schon installiert"
else
  echo "STOP: Mischstand - nichts geaendert."
  for f in "${SINGLE[@]}" pinneberg_rolle.py pinneberg_rolle.json lage_pages.py; do
    [[ -f "$DASH_DIR/$f" ]] && echo "      $f $(sfull "$DASH_DIR/$f" | cut -c1-16)" || echo "      $f fehlt"
  done
  STOPPED=1; exit 1
fi
[[ -w "$DASH_DIR" ]] || stop "Projektordner nicht beschreibbar"
"$VPY" -c "import sys; assert sys.version_info >= (3, 9)" 2>/dev/null || stop "Python der venv ($VPY) ist aelter als 3.9 oder nicht startbar"
mkdir -p "$W/alt" "$W/check"
cp "$DASH_DIR/dashboard.py" "$W/alt/dashboard.py"
cp "$W/neu/dashboard.py" "$W/neu/prepper_docs.py" "$W/neu/prepper_sdr.py" "$W/neu/pinneberg_rolle.py" "$W/check/"
cp "$DASH_DIR/lage_pages.py" "$W/check/"
python3 "$W/guard.py" check "$W/alt" "$W/check" "$VARIANT" > "$W/g.log" 2>&1 || { cat "$W/g.log"; stop "Guard $MK meldet Verstoss"; }
echo "OK $(head -1 "$W/g.log")"
MUTS=1; [[ -n "${C61_SIM_NOMUT:-}" && "$SIM" == 1 ]] && { MUTS=0; echo "SIM: Mutationstest uebersprungen"; }
if [[ "$MUTS" == 1 ]]; then
  python3 "$W/guard.py" mutate "$W/alt" "$W/check" "$VARIANT" > "$W/gm.log" 2>&1 || { cat "$W/gm.log"; stop "Mutationstest $MK: eine Veraenderung wurde nicht erkannt"; }
  echo "OK $(grep -E '^Mutationstest' "$W/gm.log")"
  grep -q "UEBERSEHEN" "$W/gm.log" && { cat "$W/gm.log"; stop "Mutationstest enthaelt UEBERSEHEN"; }
fi
for py in "$SPY" "$VPY"; do
  for x in "$W/check"/*.py "$W/guard.py"; do
    "$py" -W error -c 'import sys; compile(open(sys.argv[1], encoding="utf-8").read(), sys.argv[1], "exec")' "$x" 2>"$W/pyc.log" || { cat "$W/pyc.log"; stop "py_compile $(basename "$x") mit $py"; }
  done
done
echo "OK py_compile ($SPY und $VPY)"
role_import() {
  local py log
  rm -rf "$W/try" && mkdir -p "$W/try"
  find "$DASH_DIR" -maxdepth 1 -name '*.py' -exec ln -s {} "$W/try/" \;
  rm -f "$W/try/dashboard.py" "$W/try/prepper_docs.py" "$W/try/prepper_sdr.py" "$W/try/pinneberg_rolle.py"
  cp "$W/neu/dashboard.py" "$W/neu/prepper_docs.py" "$W/neu/prepper_sdr.py" "$W/neu/pinneberg_rolle.py" "$W/try/"
  if grep -q "rtl_fm" "$W/neu/pinneberg_rolle.py"; then stop "Rolle enthaelt rtl_fm"; fi
  slog="$W/imp-system.log"
  ( cd "$W/try" && PYTHONDONTWRITEBYTECODE=1 timeout 120 "$SPY" -c 'import pinneberg_rolle,prepper_sdr; print(pinneberg_rolle.selftest()); print(prepper_sdr.selftest_sdrstick3e())' ) > "$slog" 2>&1 || { tail -n 40 "$slog"; stop "Abhaengigkeitsfreier Selbsttest mit System-Python $SPY fehlgeschlagen"; }
  grep -q "pinnebergRolle Stufe 1 ok" "$slog" || { tail -n 20 "$slog"; stop "Rollentest fehlt ($SPY)"; }
  grep -q "selftest sdrStick3e ok" "$slog" || stop "Stick-3-Selbsttest fehlt ($SPY)"
  vlog="$W/imp-venv.log"
  ( cd "$W/try" && PYTHONDONTWRITEBYTECODE=1 timeout 180 "$VPY" -c 'import dashboard' ) > "$vlog" 2>&1 || { tail -n 40 "$vlog"; stop "Import dashboard mit der Dashboard-venv $VPY fehlgeschlagen"; }
  grep -q "pinnebergRolle aktiv:" "$vlog" || stop "Anzeige-Selbsttest fehlt ($VPY)"
  grep -q "audioKern aktiv:" "$vlog" || stop "Audio-Selbsttest fehlt ($VPY)"
  echo "OK System-Python $SPY: Rolle und Stick-3-Planer ohne Flask. Dashboard-venv $VPY: Anzeige und Audio. Kein Geraet geoeffnet, nichts gesendet."
}
role_import
code() { local c; c=$("${CURL[@]}" "$@" -o /dev/null -w "%{http_code}" || true); [[ -z "$c" ]] && c=000; echo "$c"; }
code_r() { local c i; for i in 1 2 3 4 5; do c=$(code "$@"); [[ "$c" == 200 ]] && break; sleep "${C61_RETRY_S:-6}"; done; echo "$c"; }
PAGES=(/ /speicher /funk /pi /umwelt /funk433 /aprs /meteor /rundfunk /energie /dabhist /mesh /karte /lokale-energie)
