for u in $SVCS; do ACT0[$u]=$(systemctl is-active "$u" 2>/dev/null || true); AET0[$u]=$(systemctl show -p ActiveEnterTimestamp --value "$u" 2>/dev/null || true); done
echo "Dienste vorher: $(for u in $SVCS; do printf '%s=%s ' "$u" "${ACT0[$u]}"; done)"
OURS=" dashboard.py prepper_docs.py prepper_sdr.py pinneberg_rolle.py "
others() { local f b; for f in "$DASH_DIR"/*.py; do b=$(basename "$f"); [[ "$OURS" == *" $b "* ]] || echo "$b $(s16 "$f")"; done; }
others > "$W/others0.txt"
ready_role() {
  local limit="${C61_READY_S:-180}" pause t0 now elapsed line pyrc cf
  [[ "$limit" =~ ^[0-9]+$ ]] || limit=180
  t0=$(date +%s)
  : > "$W/role-wait.log"
  while true; do
    now=$(date +%s); elapsed=$((now - t0))
    if (( elapsed >= limit )); then echo "FAIL Zeit ${limit}s" | tee -a "$W/role-wait.log"; return 1; fi
    if ! systemctl is-active --quiet prepper-dashboard; then
      echo "WAIT ${elapsed}s Dienst nicht aktiv" | tee -a "$W/role-wait.log"
    else
      cf="$W/html/pn.json"
      hc=$("${CURL[@]}" -o "$cf" -w "%{http_code}" "$B/api/pinneberg" || true)
      pf="$W/html/funk.html"
      fc=$("${CURL[@]}" -o "$pf" -w "%{http_code}" "$B/funk" || true)
      set +e
      line=$(python3 - "$cf" "$hc" "$pf" "$fc" << 'PY'
import json, sys
jp, jc, fp, fc = sys.argv[1:5]
def rd(p):
    try:
        return open(p, encoding="utf-8", errors="replace").read()
    except Exception:
        return ""
js, html = rd(jp), rd(fp)
hard = ("Traceback (most recent call last)", "jinja2.exceptions", "TemplateSyntaxError", "Internal Server Error")
hit = [s for s in hard if s in js or s in html]
if jc == "500" or fc == "500" or hit:
    print("FAIL HTTP %s/%s %s" % (jc, fc, ", ".join(hit) or "HTTP 500"))
    sys.exit(2)
if "Dashboard startet" in html or "Dashboard startet" in js:
    print("WAIT Startbildschirm")
    sys.exit(1)
if jc != "200" or fc != "200":
    print("WAIT HTTP %s/%s" % (jc, fc))
    sys.exit(1)
try:
    data = json.loads(js)
except Exception:
    print("WAIT JSON noch nicht lesbar")
    sys.exit(1)
if not isinstance(data, dict):
    print("FAIL JSON ist kein Objekt")
    sys.exit(2)
def bad(msg):
    print("FAIL " + msg)
    sys.exit(2)
if data.get("alarm") is not False:
    bad("alarm ist nicht der Wahrheitswert false")
if data.get("empfang") is not False or data.get("bias_tee") is not False:
    bad("Empfang oder Bias-Tee ist nicht false")
if data.get("rf_hz") != 147300 or data.get("if_hz") != 120147300:
    bad("Frequenz ist nicht 147300 Hz und 120147300 Hz")
if data.get("stufe") != 1:
    bad("Stufe ist nicht 1")
code = data.get("code")
txt = data.get("txt") if isinstance(data.get("txt"), str) else ""
if code == "bereit":
    if "Empfang nicht gestartet" not in txt:
        bad("bereit ohne den Satz Empfang nicht gestartet")
elif code == "stop":
    if not txt.startswith("STOP"):
        bad("stop ohne STOP-Text")
elif code == "aus":
    bad("Rolle ist aus, obwohl die Datei installiert ist")
else:
    bad("Rolle unbekannt")
if "pinnebergBox" not in html:
    bad("Kachel pinnebergBox fehlt auf der echten Seite")
print("READY HTTP 200 Rolle %s, alarm false, 147300 Hz, Kachel da" % code)
sys.exit(0)
PY
)
      pyrc=$?
      set -e
      echo "$line" | tee -a "$W/role-wait.log"
      if [[ "$pyrc" -eq 0 ]]; then echo "OK Rolle sichtbar nach ${elapsed}s"; return 0; fi
      if [[ "$pyrc" -eq 2 ]]; then return 2; fi
    fi
    pause="${C61_WAIT_S:-2}"; sleep "$pause"
  done
}
