    FINISHED=1
    echo "OK $MK laeuft schon - nichts geaendert, kein Neustart"
    echo "COMMIT offen pinnebergrolle=1 fertig (schon installiert) variante=$VARIANT lage=${LH0:0:16}"
    exit 0
  fi
  stop "$MK ist in den Dateien, aber /api/pinneberg zeigt die Rolle nicht. Details: $W/role-wait.log"
fi
rswin() { local m=$(( $1 / 60 % 60 )); [[ $m -ge 55 || $m -lt 5 ]]; }
rssec() { local hm; if [[ -n "${C61_FAKE_HM:-}" && "$SIM" == 1 ]]; then hm="$C61_FAKE_HM"; echo $(( 10#${hm%%:*} * 3600 + 10#${hm##*:} * 60 + $1 )); return; fi
  echo $(( 10#$(TZ=Europe/Berlin date +%H) * 3600 + 10#$(TZ=Europe/Berlin date +%M) * 60 + 10#$(TZ=Europe/Berlin date +%S) + $1 )); }
rshm() { printf '%02d:%02d' $(( $1 / 3600 % 24 )) $(( $1 / 60 % 60 )); }
rscheck() { local s0 s1; s0=$(rssec 0); s1=$(rssec 300)
  if rswin "$s0" || rswin "$s1"; then
    if [[ "$DRY" == 1 ]]; then echo "HINWEIS Neustart-Sperre: jetzt ($1, $(rshm "$s0") Uhr Berlin) waere ein echter Lauf gesperrt (HH:50 bis HH:04 inklusive) - frei ab HH:05. apt braucht 15 Minuten Vorlauf und wird von diesem Skript nicht ausgefuehrt."
    else stop "Neustart-Sperre: es ist $(rshm "$s0") Uhr (Berlin) - Sperre HH:50 bis HH:04 inklusive - prepper-dashboard wird jetzt nicht neu gestartet; bitte ab HH:05 erneut starten"; fi
  else echo "OK Neustart-Sperre: $(rshm "$s0") Uhr (Berlin) liegt ausserhalb HH:50 bis HH:04, auch in 5 min ($1)"; fi; }
rscheck "Vorpruefung"
if [[ "$DRY" == 1 ]]; then
  FINISHED=1
  echo "TROCKENLAUF fertig - nichts installiert, kein apt, kein Neustart, prepper-sdr unangetastet. Variante $VARIANT."
  echo "COMMIT offen pinnebergrolle=dry fertig"
  exit 0
fi
sudo -v || stop "sudo -v fehlgeschlagen (Passwort noetig?)"
waitd() { local i; for i in $(seq 1 80); do sleep "${C61_WAIT_S:-3}"; systemctl is-active --quiet prepper-dashboard && [[ "$(code "$B/")" == 200 ]] && return 0; done; return 1; }
rb() {
  set +e +o pipefail
  trap - ERR
  RB_DONE=1
  echo "ROLLBACK: $1"
  local x
  for x in "${INST[@]}"; do
    if [[ -f "$x.bak-$NM-$TS" ]]; then cp -a "$x.bak-$NM-$TS" "$x.rb" && mv -f "$x.rb" "$x"
    elif [[ " ${CREATED[*]:-} " == *" $x "* ]]; then rm -f -- "$x"; fi
  done
  for x in "${INST[@]}"; do
    if [[ -f "$x.bak-$NM-$TS" ]]; then cmp -s "$x" "$x.bak-$NM-$TS" && echo "  $(basename "$x") = Sicherung" || echo "  WARNUNG $(basename "$x") ungleich Sicherung"
    elif [[ ! -e "$x" ]]; then echo "  $(basename "$x") entfernt (war neu)"; fi
  done
  [[ "$(sfull "$DASH_DIR/lage_pages.py")" == "$LH0" ]] && echo "  lage_pages.py unveraendert (${LH0:0:16})" || echo "  WARNUNG lage_pages.py veraendert"
  if [[ "$RESTARTED" == 1 ]]; then sudo systemctl restart prepper-dashboard.service 9>&-; waitd; fi
  echo "alter Stand wieder aktiv: prepper-dashboard=$(systemctl is-active prepper-dashboard 2>/dev/null), HTTP / = $(code "$B/")"
  echo "  prepper-sdr wurde nicht neu gestartet; upsmon, Firewall, Mesh und Paketquellen unveraendert; nichts gesendet"
}
rbx() { rb "$1"; exit 1; }
