[[ "$(sfull "$DASH_DIR/prepper_docs.py")" == "${NEU[prepper_docs.py]}" ]] || rbx "prepper_docs.py nach dem Kopieren falsch"
[[ "$(sfull "$DASH_DIR/prepper_sdr.py")" == "${NEU[prepper_sdr.py]}" ]] || rbx "prepper_sdr.py nach dem Kopieren falsch"
